import { createApp, ref, computed, onMounted, onUnmounted, watch } from 'vue/dist/vue.esm-bundler.js';
import { Bike, Activity, Heart, Bluetooth, Download, Smartphone, ArrowUpRight, Play, Pause, Square, Plus, Minus, Settings2, CalendarDays, Radio, ChevronRight, Timer, Mountain, X, Check, Zap } from 'lucide-vue-next';
import './style.css';
import './live-training.css';
import {WorkoutTimeline, PowerMountain} from './training-ui';
import {CockpitFeatures} from './cockpit-features';
import {WorkoutCatalog,TrainingCoach,SegmentPreview} from './workout-library';
import {VirtualRoutes} from './virtual-routes';
import {FullscreenTrainingView,useCockpitFullscreen} from './immersive-cockpit';

createApp({
 components: { FullscreenTrainingView, WorkoutCatalog, TrainingCoach, SegmentPreview, VirtualRoutes, CockpitFeatures, WorkoutTimeline, PowerMountain, Bike, Activity, Heart, Bluetooth, Download, Smartphone, ArrowUpRight, Play, Pause, Square, Plus, Minus, Settings2, CalendarDays, Radio, ChevronRight, Timer, Mountain, X, Check, Zap },
 setup() {
  const state = ref<any>({mode:'demo',target:100,power:0,cadence:0,speed:0,elapsed:0,distance:0,energy:0,history:[],zwift:'Aus'});
  const plans = ref<any[]>([]), rides = ref<any[]>([]), sensors = ref<any[]>([]);
  const tab = ref('Cockpit'), modal = ref(''), busy = ref(false), message = ref(''), online = ref(false), selected = ref<number|null>(null);
  const fullscreen=useCockpitFullscreen(tab,state);
  async function fullscreenAction(path:string){
   if(path==='start'){await fullscreen.exit();preflight();}
   else await action(path);
  }
  const riderKg = ref(85), bikeKg = ref(10);
  const appUrl=location.origin;
  const view=ref(localStorage.getItem('studio-view')||'timeline'), trainingMode=ref('power'), intensity=ref(100);
  const filterMinutes=ref(0), filterCategory=ref('Alle'), cardioMinutes=ref(35), hrLow=ref<any>(''), hrHigh=ref<any>('');
  const profile=ref<any>({ftp_watts:null,hr_max:null,hr_ceiling:null,comfortable_watts:null,hr_min_watts:25,hr_max_watts:150,power_adjustment_watts:0});
  const users=ref<any[]>([]), activeUser=ref<number|null>(null), userName=ref('');
  const profileForm=ref<any>({...profile.value});
  const profileUserId=ref<number|null>(null);
  const connectionResults=ref<any[]>([]);
  const productName=ref('Fitness-Cockpit'),selectedDevices=ref<string[]>(['daum','hr']);
  const completed=ref<any>(null),completionSeen=ref('');
  const validationToken=ref<string|null>(null),powerDraft=ref<number|null>(null),powerSending=ref(false);
  const rideTrace=ref<any>(null),pendingAction=ref<string|null>(null);
  async function openRideTrace(ride:any){modal.value='trace';rideTrace.value=null;busy.value=true;message.value='';try{rideTrace.value=await request('rides/'+ride.id+'/export/json');}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
  const eventLabel=(source:string)=>({plan:'Trainingsplan',manual_slider:'Manuell · Schieberegler',manual_button:'Manuell · Taste',return_to_plan:'Zurück zum Plan',safety:'Sicherheitsregel','pause/resume':'Pause / Fortsetzen'}[source]||source);
  const navigation=[{key:'Cockpit',label:'Training',path:'training',icon:'Activity'},{key:'Trainingspläne',label:'Trainingskatalog',path:'trainings',icon:'CalendarDays'},{key:'KI-Coach',label:'KI-Coach',path:'coach',icon:'Zap'},{key:'Aktivitäten',label:'Historie',path:'history',icon:'Timer'},{key:'Planer',label:'Planer',path:'planner',icon:'CalendarDays'},{key:'Virtuelle Strecken',label:'Strecken',path:'routes',icon:'Mountain'},{key:'Verbindungen',label:'Verbindungen',path:'devices',icon:'Bluetooth'}];
  const navLabel=computed(()=>navigation.find(item=>item.key===tab.value)?.label||tab.value);
  function readRoute(){const route=location.hash.replace(/^#\/?/,'');const item=navigation.find(n=>n.path===route);if(item)tab.value=item.key;}
  watch(tab,value=>{const item=navigation.find(n=>n.key===value);if(item&&location.hash!=='#/'+item.path)history.replaceState(null,'','#/'+item.path);});
  const powerLimits=computed(()=>state.value.power_limits||{minimum:25,maximum:400,step:5});
  const displayedTarget=computed(()=>powerDraft.value??state.value.requested_target_watts??state.value.target);
  const commandLabel=computed(()=>{
   if(powerSending.value||powerDraft.value!==null)return 'Neue Vorgabe wird übermittelt';
   const status=state.value.target_command_status;
   if(status==='simulated'||state.value.mode==='demo')return 'Simulation · keine reale Gerätebestätigung';
   if(status==='applied'&&state.value.applied_target_watts!=null)return state.value.applied_target_watts+' W vom Gerät zurückgemeldet';
   if(status==='adjusted'&&state.value.applied_target_watts!=null)return state.value.applied_target_watts+' W zurückgemeldet · Vorgabe abweichend';
   if(status==='unconfirmed')return 'Gerätevorgabe nicht bestätigt';
   return status==='paused'?'Pausiert · Vorgabe für Fortsetzen':status==='unsupported'?'Steuerung nicht unterstützt':status==='error'?'Gerätebefehl fehlgeschlagen':'Geräterückmeldung ausstehend';
  });
  let powerTimer:any=null,powerVersion=0,powerQueued:any=null;
  function clearPowerQueue(){powerVersion++;clearTimeout(powerTimer);powerQueued=null;powerDraft.value=null;}
  async function drainPower(){
   if(powerSending.value||!powerQueued)return;
   const job=powerQueued;powerQueued=null;powerSending.value=true;
   try{const result=await request('power',{watts:job.watts,source:job.source,expected_user_id:job.userId,expected_session_id:job.sessionId});if(job.version===powerVersion&&job.userId===activeUser.value){state.value=result;powerDraft.value=null;}}
   catch(e:any){if(job.version===powerVersion){message.value=e.message;powerDraft.value=null;}}
   finally{powerSending.value=false;if(powerQueued)powerTimer=setTimeout(drainPower,0);}
  }
  function setPower(watts:number,source='manual_button'){
   if(manualLocked.value||!Number.isFinite(watts))return;
   const limits=powerLimits.value;
   const desired=Math.max(limits.minimum,Math.min(limits.maximum,Math.round(watts)));
   powerDraft.value=desired;
   powerQueued={watts:desired,source,userId:activeUser.value,sessionId:state.value.running?state.value.session_id:undefined,version:++powerVersion};
   clearTimeout(powerTimer);powerTimer=setTimeout(drainPower,source==='manual_slider'?180:0);
  }
  async function returnToPlan(){clearPowerQueue();await action('power/plan',{expected_session_id:state.value.running?state.value.session_id:undefined});}
  watch(()=>state.value.running,(value,previous)=>{if(previous&&!value)clearPowerQueue();});
  watch(activeUser,()=>{clearPowerQueue();validationToken.value=null;});
  const formatValue=(v:any,digits=0)=>v==null?'—':Number(v).toLocaleString('de-DE',{maximumFractionDigits:digits});
  const metric=(key:string)=>online.value&&(key==='heart_rate'||state.value.running&&!state.value.paused)&&state.value.measurements?.[key]?.available&&!state.value.measurements?.[key]?.stale?state.value.measurements[key].value:null;
  const source=(key:string)=>{const m=state.value.measurements?.[key];if(key==='speed'&&state.value.speed_measurement_note)return 'Einheit ungeprüft';return m?.source==='demo'?'Simuliert':m?.source==='daum'?'Daum-Gerät':m?.source==='ble'?'BLE-Sensor':m?.source==='calculated'||m?.source==='integrated_power'?'Berechnet':m?.source||'Nicht verfügbar';};
  async function selectPlanId(id:number){await load();const plan=plans.value.find(p=>p.id===id);if(plan)choosePlan(plan);}
  async function preparePlanId(id:number,token?:string){await selectPlanId(id);trainingMode.value='power';validationToken.value=token||null;preflight();}
  watch(()=>state.value.completion,async value=>{
   if(!value||value.user_id!==activeUser.value)return;
   const key=String(value.user_id)+':'+String(value.ride_id);
   if(completionSeen.value===key)return;
   completionSeen.value=key;await load();
   if(value.reason==='completed'){await fullscreen.exit();completed.value=value;modal.value='completion';}
  });
  const powerSettings=ref<any>({available:false,enabled:false,delay_seconds:300});
  async function openSettings(){modal.value='settings';message.value='';try{powerSettings.value=await request('power-settings');}catch(e:any){message.value=e.message;}}
  async function toggleAutoOff(){busy.value=true;message.value='';try{powerSettings.value=await request('power-settings',{enabled:!powerSettings.value.enabled});}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
  let loadPending:Promise<void>|null=null;
  const planName = ref('Mein Training'), steps = ref([{name:'Warm-up',seconds:300,watts:60},{name:'Grundlage',seconds:900,watts:120},{name:'Ausrollen',seconds:300,watts:50}]);
  let socket:WebSocket, reconnect:any, disposed=false;
  const clock = (seconds=0) => `${Math.floor(seconds/60).toString().padStart(2,'0')}:${Math.floor(seconds%60).toString().padStart(2,'0')}`;
  const chart = computed(() => {let drawing=false;return state.value.history.map((p:number|null,i:number)=>{if(p==null||!Number.isFinite(p)){drawing=false;return '';}const command=(drawing?'L':'M')+(i*600/89)+','+(110-p/4);drawing=true;return command;}).join(' ');});
  const duration = (plan:any) => Math.round(plan.steps.reduce((s:number,x:any)=>s+x.seconds,0)/60);
  const selectedPlan = computed(()=>plans.value.find(p=>p.id===selected.value));
  const visiblePlans=computed(()=>plans.value.filter(p=>(!filterMinutes.value||duration(p)===Number(filterMinutes.value))&&(filterCategory.value==='Alle'||(p.meta?.category||'Eigene')===filterCategory.value)));
  const previewSteps=computed(()=>{
   if(state.value.running)return state.value.steps||[];
   if(!selectedPlan.value)return state.value.steps||[];
   const plan=selectedPlan.value;
   const scale=plan.meta?.calibration?100:Number(intensity.value);
   return plan.steps.map((s:any)=>({...s,watts:Math.max(25,Math.min(400,Math.round((s.reference_watts??s.watts)*scale/100)+(plan.power_adjustment_watts||0)))}));
  });
  const previewElapsed=computed(()=>state.value.running||!selectedPlan.value?state.value.elapsed:0);
  const manualLocked=computed(()=>busy.value||!online.value||state.value.pending_save||state.value.zwift_detail?.armed||(state.value.mode!=='demo'&&!state.value.capabilities?.control?.includes('power')));
  const startBlocker=computed(()=>!online.value?'Serververbindung fehlt.':powerSending.value||powerDraft.value!==null?'Neue Wattvorgabe wird noch übermittelt.':state.value.running?'Training läuft bereits.':state.value.zwift_detail?.armed?'Zuerst Zwift-Steuerung sperren.':state.value.mode==='daum'&&!state.value.connected?'Zuerst Daum verbinden.':selectedPlan.value&&!validationToken.value?'Profil vor Start prüfen.':trainingMode.value==='hr'&&(!profile.value.hr_max||!profile.value.hr_ceiling)?'Persönliche HFmax und Pulsgrenze fehlen.':trainingMode.value==='hr'&&(!state.value.hr_connected||!state.value.hr_fresh)?'Pulsmodus benötigt ein frisches Pulssignal.':trainingMode.value==='hr'&&state.value.heart_rate>=profile.value.hr_ceiling?'Persönliche Pulsgrenze bereits erreicht.':'');
  async function validateSelectedPlan(){
   if(!selected.value)return true;
   busy.value=true;message.value='';validationToken.value=null;
   try{
    const plan=await request('catalog/'+selected.value);
    const check={expected_user_id:activeUser.value,expected_revision:plan.revision,intensity_percent:selectedPlan.value?.meta?.calibration?100:Number(intensity.value),training_mode:trainingMode.value};
    await request('catalog/'+selected.value+'/accept',check);
    const validated=await request('catalog/'+selected.value+'/validate',check);
    const ready=await request('catalog/'+selected.value+'/prepare',{...check,validation_token:validated.validation_token});
    validationToken.value=ready.validation_token;return true;
   }catch(e:any){message.value=e.message;return false;}finally{busy.value=false;}
  }
  function preflight(){message.value='';sensors.value=[];modal.value='preflight';if(selected.value&&!validationToken.value)validateSelectedPlan();}
  watch([selected,intensity,trainingMode],()=>validationToken.value=null,{flush:'sync'});
  watch(()=>state.value.mode,()=>validationToken.value=null);
  const progress = computed(()=>state.value.duration ? Math.min(100,state.value.elapsed/state.value.duration*100):0);
  async function request(path:string,body?:any) {
   const controller=new AbortController();
   const timer=setTimeout(()=>controller.abort(),path==='connect/all'?55000:path==='coach/suggest'?60000:30000);
   try{
    const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});
    const data=await response.json().catch(()=>({}));
    if(!response.ok){
     const fields:any={watts:'Leistung',seconds:'Abschnittsdauer',duration_seconds:'Gesamtdauer',name:'Name',steps:'Trainingsabschnitte',power_min_watts:'Watt-Untergrenze',power_max_watts:'Watt-Obergrenze',weight_kg:'Gewicht',birth_year:'Geburtsjahr',height_cm:'Größe'};
     const invalid=Array.isArray(data.detail)?[...new Set(data.detail.map((v:any)=>fields[v.loc?.at(-1)]||'Eingaben'))].join(', '):null;
     throw Error(typeof data.detail==='string'?data.detail:invalid?'Bitte '+invalid+' und die angezeigten Grenzen prüfen.':'Bitte Eingaben prüfen oder Verbindung erneut versuchen.');
    }
    return data;
   }catch(e:any){
    if(e.name==='AbortError')throw Error('Keine rechtzeitige Antwort. Verbindung prüfen und erneut versuchen.');
    if(e instanceof TypeError)throw Error('Server nicht erreichbar. Verbindung zum Pi prüfen.');
    throw e;
   }finally{clearTimeout(timer);}
  }
  async function action(path:string,body:any={}) {if(path==='stop'||path==='start'||path==='mode')clearPowerQueue();pendingAction.value=path;busy.value=true;message.value='';try{state.value=await request(path,{expected_user_id:activeUser.value,...body});if(path==='stop'||path.startsWith('calibration/'))await load();return true;}catch(e:any){message.value=e.message;return false;}finally{busy.value=false;pendingAction.value=null;}}
  function load():Promise<void>{
   if(loadPending)return loadPending;
   loadPending=(async()=>{try{
    const data=await request('session');
    if(activeUser.value!==null&&activeUser.value!==data.active_user_id){selected.value=null;hrLow.value='';hrHigh.value='';sensors.value=[];connectionResults.value=[];}
    plans.value=data.plans;rides.value=data.rides;profile.value=data.profile;
    users.value=data.users;activeUser.value=data.active_user_id;
    profileForm.value={...profile.value};profileUserId.value=activeUser.value;
   }catch(e:any){message.value=e.message;}})().finally(()=>{loadPending=null;});
   return loadPending;
  }
  async function connectAll(){
   busy.value=true;message.value='';connectionResults.value=[];sensors.value=[];
   try{
    const result=await request('connect/all',{expected_user_id:activeUser.value,devices:selectedDevices.value});
    state.value=result.state;sensors.value=result.sensors;connectionResults.value=result.results;
    if(result.needs_sensor_choice&&modal.value!=='preflight')modal.value='hr';
   }catch(e:any){message.value=e.message;}finally{busy.value=false;}
  }
  function adjustProfile(watts:number){profileForm.value.power_adjustment_watts=Math.max(-100,Math.min(100,Number(profileForm.value.power_adjustment_watts||0)+watts));}
  function connect(){if(disposed)return; socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);socket.onopen=()=>online.value=true;socket.onmessage=e=>{state.value=JSON.parse(e.data);if(!busy.value&&activeUser.value!==null&&state.value.user_id!==activeUser.value)load();};socket.onclose=()=>{online.value=false;if(!disposed)reconnect=setTimeout(connect,2000)};socket.onerror=()=>socket.close();}
  async function scan(){busy.value=true;message.value='';try{sensors.value=await request('hr/scan');if(!sensors.value.length)message.value='Kein Bluetooth-Pulsgurt gefunden. Gurt anlegen und Elektroden anfeuchten.';}catch(e:any){message.value=e.message}finally{busy.value=false}}
  async function save(){busy.value=true;message.value='';try{await request('plans',{name:planName.value,steps:steps.value});await load();modal.value='';tab.value='Trainingspläne';}catch(e:any){message.value=e.message}finally{busy.value=false}}
  async function startWithoutHr(){trainingMode.value='power';if(selected.value&&!await validateSelectedPlan())return;await start();}
  async function start(){if(powerSending.value||powerDraft.value!==null){message.value='Neue Wattvorgabe wird noch übermittelt.';return;}const started=await action('start',{expected_user_id:activeUser.value,validation_token:validationToken.value,plan_id:selected.value,training_mode:trainingMode.value,intensity_percent:selectedPlan.value?.meta?.calibration?100:Number(intensity.value),duration_minutes:Number(cardioMinutes.value),hr_target_low:hrLow.value?Number(hrLow.value):null,hr_target_high:hrHigh.value?Number(hrHigh.value):null});if(started){modal.value='';tab.value='Cockpit';}}
  function setView(value:string){view.value=value;localStorage.setItem('studio-view',value);}
  function choosePlan(plan:any){validationToken.value=null;selected.value=plan.id;if(plan.meta?.terrain)trainingMode.value='power';intensity.value=100;setView('timeline');tab.value='Cockpit';}
  function editPlan(plan:any){planName.value=plan.name+' · eigene Wattwerte';steps.value=plan.steps.map((s:any)=>({name:s.name,seconds:s.seconds,watts:Math.max(25,Math.min(400,Math.round(s.reference_watts??s.watts)))}));modal.value='plan';}
  function openProfile(){profileForm.value={...profile.value};profileUserId.value=activeUser.value;modal.value='profile';}
  async function saveProfile(){busy.value=true;message.value='';try{const values=Object.fromEntries(Object.entries(profileForm.value).map(([k,v])=>[k,v===''||v===null?null:k==='sex'?v:Number(v)]));profile.value=await request('profile',{...values,expected_user_id:profileUserId.value});await load();modal.value='';}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
  async function switchUser(id:number){busy.value=true;message.value='';try{await request(`users/${id}/activate`,{});state.value=await request('state');selected.value=null;hrLow.value='';hrHigh.value='';completed.value=null;completionSeen.value='';await load();}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
  async function createUser(){busy.value=true;message.value='';try{const user=await request('users',{name:userName.value.trim()});await switchUser(user.id);userName.value='';}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
  async function renameUser(){busy.value=true;message.value='';try{await request(`users/${activeUser.value}/rename`,{name:userName.value.trim()});await load();userName.value='';}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
  async function deleteRide(ride:any){if(!window.confirm('Diese Fahrt einschließlich aller Messwerte dauerhaft löschen?'))return;busy.value=true;message.value='';try{await request(`rides/${ride.id}/delete`,{expected_user_id:activeUser.value});await load();}catch(e:any){message.value=e.message;}finally{busy.value=false;}}
  onMounted(()=>{readRoute();window.addEventListener('hashchange',readRoute);load();connect();request('config').then(c=>{productName.value=c.product_name||'Fitness-Cockpit';document.title=productName.value+' · Training';document.querySelector('meta[name=apple-mobile-web-app-title]')?.setAttribute('content',productName.value);}).catch(()=>{});});onUnmounted(()=>{disposed=true;clearPowerQueue();window.removeEventListener('hashchange',readRoute);clearTimeout(reconnect);socket?.close()});
  return {fullscreen,fullscreenAction,pendingAction,openRideTrace,rideTrace,eventLabel,validateSelectedPlan,navigation,navLabel,powerLimits,displayedTarget,powerSending,powerDraft,commandLabel,returnToPlan,preparePlanId,validationToken,productName,selectedDevices,completed,formatValue,metric,source,selectPlanId,load,request,powerSettings,openSettings,toggleAutoOff,deleteRide,connectAll,connectionResults,adjustProfile,preflight,startWithoutHr,startBlocker,users,activeUser,userName,switchUser,createUser,renameUser,state,plans,rides,sensors,tab,modal,busy,message,online,selected,riderKg,bikeKg,planName,steps,clock,chart,duration,selectedPlan,progress,action,scan,save,start,setPower,view,setView,trainingMode,intensity,filterMinutes,filterCategory,cardioMinutes,hrLow,hrHigh,profile,profileForm,visiblePlans,previewSteps,previewElapsed,manualLocked,choosePlan,editPlan,openProfile,saveProfile,appUrl};
 },
 template: `
 <div class="shell" :class="{'training-active':state.running}">
  <aside class="sidebar" :inert="fullscreen.active" :aria-hidden="fullscreen.active?true:undefined">
   <a class="brand" href="/"><span class="brand-icon"><Bike :size="24"/></span><span>{{productName}}<span class="brand-sub">DEIN TRAINING</span></span></a>
   <div class="nav-label">DEIN TRAINING</div>
   <nav><button :aria-label="item.label" v-for="item in navigation" :class="{active:tab===item.key}" @click="tab=item.key"><component :is="item.icon" :size="20"/><span>{{item.label}}</span><ChevronRight v-if="tab===item.key" :size="15"/></button></nav>
   <div class="sidebar-bottom"><div class="device-icon"><Bike :size="24"/></div><b>Dein Klassiker. Neuer Antrieb.</b><p>Daum Premium 8i<br>Raspberry Pi · GHAPI3</p><div class="statusline"><i :class="{good:online}"></i>{{online?'Cockpit verbunden':'Verbindung wird aufgebaut'}}</div><small>LOKAL. DEIN RIDE. DEINE DATEN.</small></div>
  </aside>
  <main :inert="fullscreen.active" :aria-hidden="fullscreen.active?true:undefined">
   <header><div class="breadcrumb">DEIN FITNESS-COCKPIT <span>/ {{navLabel}}</span></div><div class="header-right"><span class="pill" :class="{demo:state.mode==='demo'}"><i></i>{{state.mode==='demo'?'Demo-Modus':state.connected?'Daum verbunden':'Daum getrennt'}}</span><label>Benutzer <select aria-label="Benutzer auswählen" :value="activeUser" :disabled="busy||state.running||state.zwift_detail?.armed" @change="switchUser(Number($event.target.value))"><option v-for="user in users" :value="user.id">{{user.name}}</option></select></label><button class="text-button" @click="openProfile">Profile</button></div></header>
   <div class="page-heading"><div><p class="eyebrow">READY WHEN YOU ARE</p><h1>{{tab==='Cockpit'?'Zeit für dein Training.':navLabel}}</h1><p>{{tab==='Cockpit'?'Einsteigen. Abschalten. Weiterkommen.':tab==='Trainingspläne'?'Deine Ziele. Dein Tempo. Dein nächster Schritt.':tab==='Verbindungen'?'Bike, Pulsgurt und Zwift an einem Ort.':'Jeder Ride zählt.'}}</p></div><div class="heading-actions"><button class="button secondary" :disabled="busy||!online||state.running||state.zwift_detail?.armed" @click="connectAll"><Bluetooth :size="17"/>{{busy?'Bitte warten …':'Alles verbinden'}}</button><button class="button secondary" @click="openSettings"><Settings2 :size="17"/> Einstellungen</button></div></div>
   <div v-if="message || state.error" class="alert" role="alert">{{message || state.error}}<button @click="message=''" aria-label="Meldung schließen"><X :size="18"/></button></div>
   <fieldset class="device-selection"><legend>Zu verbindende Geräte</legend><label><input type="checkbox" value="daum" v-model="selectedDevices">Daum-Ergometer</label><label><input type="checkbox" value="hr" v-model="selectedDevices">Pulsgurt</label><label><input type="checkbox" value="zwift" v-model="selectedDevices">Zwift-Sender (optional)</label></fieldset><div v-if="connectionResults.length" class="connection-results" role="status"><p v-for="result in connectionResults" :class="{failed:!result.ok}"><Check v-if="result.ok" :size="16"/><Bluetooth v-else :size="16"/><b>{{result.device==='daum'?'Daum':result.device==='zwift'?'Zwift-Sender':'Pulssensor'}}:</b> {{result.message}}</p></div>
   <div v-if="busy&&state.connections" class="connection-progress" role="status"><span v-for="(status,device) in state.connections">{{device}}: {{status.message||status.phase||status.status}}</span></div><div v-if="state.pending_save" class="alert" role="alert">Die Einheit konnte noch nicht gespeichert werden. <button class="button secondary" :disabled="busy||!online" @click="action('stop')">Speichern erneut versuchen</button></div><div v-if="!online" class="alert">Serververbindung unterbrochen. Bediene das Bike bei Bedarf direkt am Cockpit.</div>
   <template v-if="tab==='Cockpit'">
    <section class="training-toolbar card"><label class="training-select">Training<select aria-label="Training auswählen" v-model="selected" :disabled="state.running||busy"><option :value="null">Freies Training / Puls-Cardio</option><option v-for="plan in plans" :value="plan.id">{{plan.name}} · {{duration(plan)}} min</option></select></label><div class="mode-choice" aria-label="Trainingssteuerung"><button :class="{chosen:trainingMode==='power'}" :disabled="state.running" @click="trainingMode='power'">Wattgeführt</button><button :class="{chosen:trainingMode==='hr'}" :disabled="state.running" @click="trainingMode='hr'">Pulsgeführt</button></div><label v-if="selectedPlan" class="intensity-control">Watt-Intensität · {{selectedPlan.meta?.calibration?100:intensity}} %<input aria-label="Trainingsintensität in Prozent" type="range" min="50" max="130" step="5" v-model.number="intensity" :disabled="state.running||trainingMode==='hr'||selectedPlan.meta?.calibration"></label><button class="text-button" @click="openProfile">Persönliche Werte <Settings2 :size="15"/></button><span v-if="profile.power_adjustment_watts" class="profile-adjustment-summary">Profilanpassung: {{profile.power_adjustment_watts>0?'+':''}}{{profile.power_adjustment_watts}} W</span><p v-if="selectedPlan?.power_basis==='example'" class="training-hint">Ohne FTP: Wattkurve mit Beispielbasis 150 W. Du kannst direkt starten und die Wattwerte über Intensität oder Profilanpassung ändern.</p><div v-if="trainingMode==='hr'" class="hr-setup"><span><Heart :size="16"/>{{profile.hr_max?'HFmax '+profile.hr_max+' · Pulsgrenze '+(profile.hr_ceiling||'fehlt')+' bpm':'Zuerst persönliche HFmax und Pulsgrenze eintragen.'}}</span><template v-if="!selectedPlan"><label>Dauer<select v-model.number="cardioMinutes" :disabled="state.running"><option :value="35">35 min</option><option :value="45">45 min</option><option :value="60">60 min</option></select></label><label>Pulsziel von<input v-model.number="hrLow" type="number" :placeholder="profile.hr_max?Math.round(profile.hr_max*.60):'bpm'" :disabled="state.running"></label><label>bis<input v-model.number="hrHigh" type="number" :placeholder="profile.hr_max?Math.round(profile.hr_max*.70):'bpm'" :disabled="state.running"></label></template><small>Nur mit frischem Gurtsignal. Wattgrenze {{profile.hr_max_watts}} W; kein künstlicher Puls in der Demo.</small></div></section>
    <section v-if="state.running&&state.training_mode==='hr'" class="pulse-live card"><Heart :size="24"/><div><span>DEINE PULS-ZIELZONE</span><b>{{state.hr_target?.low}}–{{state.hr_target?.high}} <small>bpm</small></b></div><div class="pulse-live-current"><span>AKTUELL</span><b>{{state.heart_rate??'—'}} <small>bpm</small></b></div><p>{{state.pulse_status}}</p></section>


    <section v-if="state.calibrating&&state.running" class="calibration-live card"><div><p class="eyebrow">ORIENTIERUNG · KEIN MAXIMALTEST</p><h3>Wie fühlt sich diese Stufe an?</h3><p>Nach mindestens einer Minute gleichmäßigem Treten: Kannst du entspannt ganze Sätze sprechen? Nur dann als lockere Ausgangsleistung markieren. Nicht bis zur Erschöpfung fahren.</p><small>{{profile.comfortable_watts?'Zuletzt als locker markiert: '+profile.comfortable_watts+' W. Das ist keine FTP.':'Noch keine Stufe eingeordnet. Es wird kein Wert automatisch als FTP oder HFmax gespeichert.'}}</small></div><div class="calibration-actions"><button class="button secondary" :disabled="busy||state.paused||state.mode==='demo'" @click="action('calibration/comfortable')">Gut sprechbar · diese Wattstufe merken</button><button class="button stop" :disabled="busy" @click="action('stop')">Zu anstrengend · beenden</button></div></section>
    <div class="training-dashboard"><div class="dashboard-grid">
     <section class="ride-scene card" :class="{'training-view':view!=='ride'}">
      <div class="scene-heading"><div class="view-switch" aria-label="Cockpit-Ansicht"><button :class="{chosen:view===name}" v-for="(label,name) in {ride:'Rad',timeline:'Zeitachse',mountain:'Berg'}" @click="setView(name)">{{label}}</button></div><div class="fullscreen-entry" role="group" aria-label="Vollbild öffnen"><button aria-label="Zeitachse im Vollbild" title="Zeitachse im Vollbild" @click="fullscreen.enter('timeline')">⛶ Zeitachse</button><button aria-label="Kennzahlen im Vollbild" title="Alle Kennzahlen im Vollbild" @click="fullscreen.enter('metrics')">⛶ Kennzahlen</button></div></div>
      <div v-if="view==='ride'" class="scene-copy"><h2>Nur du.<br>Und der nächste Kilometer.</h2><p>{{state.mode==='demo'?'Virtuelle Fahrt · simulierte Bike-Daten':'Dein Daum · echte Bike-Daten'}}</p></div>
      <svg v-if="view==='ride'" class="landscape" viewBox="0 0 900 390" preserveAspectRatio="xMidYMax slice" aria-label="Animierte Radfahrt durch eine Berglandschaft" role="img">
       <defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#a1bbab"/><stop offset="1" stop-color="#e5dec1"/></linearGradient><linearGradient id="hill" x2="0" y2="1"><stop stop-color="#3b6b58"/><stop offset="1" stop-color="#153f34"/></linearGradient></defs>
       <rect width="900" height="390" fill="url(#sky)"/><circle cx="720" cy="65" r="40" fill="#f9e2ad"/>
       <path d="M0 210L120 110 220 172 360 70 500 179 650 90 780 161 900 70V390H0Z" fill="#91aa95"/><path d="M0 260L130 171 310 244 460 143 650 235 800 156 900 200V390H0Z" fill="#6e927c"/>
       <path d="M0 290Q180 195 400 270T900 250V390H0Z" fill="url(#hill)"/><path d="M0 385Q260 250 900 345" fill="none" stroke="#d7c8a0" stroke-width="70"/><path d="M0 385Q260 250 900 345" fill="none" stroke="#ecdfbb" stroke-width="2" stroke-dasharray="26 24" class="road" :style="{'animationPlayState':state.running&&!state.paused?'running':'paused'}"/>
       <g v-for="x in [60,130,745,820]" :transform="'translate('+x+',240)'" fill="#244c3c"><path d="M0 0L-16 36H16ZM0 17L-21 52H21Z"/><path d="M-3 40H3V65H-3Z"/></g>
       <g transform="translate(410,245)"><ellipse cx="32" cy="99" rx="100" ry="9" fill="#102c24" opacity=".16"/>
        <g v-for="x in [-34,97]" :transform="'translate('+x+',55)'"><g class="wheel" :style="{'animationDuration':(60/Math.max(state.cadence,1))+'s','animationPlayState':state.cadence>0?'running':'paused'}"><circle r="39" fill="#c6c4a5" stroke="#17392f" stroke-width="6"/><path d="M-35 0H35M0-35V35M-25-25L25 25M-25 25L25-25" stroke="#52695a" stroke-width="1.5"/></g></g>
        <path d="M-34 55L0-4 38 55H-34L24 7H74L97 55M38 55L74 7 67-14H84M-10-6H13" fill="none" stroke="#f28d4f" stroke-width="6" stroke-linejoin="round" stroke-linecap="round"/>
        <path d="M4-9L19-48 59-57 77-20" fill="none" stroke="#eeceac" stroke-width="12" stroke-linecap="round"/><path d="M16-45L48-63 61-49" fill="none" stroke="#faf0dc" stroke-width="23" stroke-linejoin="round"/><circle cx="65" cy="-81" r="12" fill="#eeceac"/><path d="M50-84Q56-103 78-88" stroke="#e08047" stroke-width="9" fill="none"/><path d="M8-15L35 10 35 53" fill="none" stroke="#1c322b" stroke-width="12" stroke-linecap="round"/>
       </g>
      </svg>
      <WorkoutTimeline v-if="view==='timeline'" :steps="previewSteps" :elapsed="previewElapsed" :samples="state.running||!selectedPlan?state.samples||[]:[]" :power="metric('power')" :heart-rate="metric('heart_rate')" :live="state.running&&!state.paused" :target="state.target" :control-events="state.control_events||[]" :offset="state.power_offset_watts||0" :limits="powerLimits" :ftp="profile.ftp_watts||150"/><PowerMountain v-if="view==='mountain'" :watts="state.running?metric('power'):selectedPlan?previewSteps[0]?.watts||0:state.target" :source-label="state.running?(state.mode==='demo'?'Simulierte Leistung':'Ist-Leistung'):'Planvorschau'" :ftp="profile.ftp_watts||150" :steps="previewSteps" :elapsed="previewElapsed"/>
      <div class="scene-footer"><span><i></i>{{state.running?state.plan_name:selectedPlan?.name||state.plan_name||'Freies Training'}}</span><span>{{state.running?state.step_name:selectedPlan?'Planvorschau':state.step_name}} {{state.running&&state.steps?.length?'· '+clock(state.step_remaining):''}} <ArrowUpRight :size="15"/></span></div>
     </section>
     <section class="power-card card live-power-card"><div class="section-title"><span><Zap :size="17"/> IST-LEISTUNG</span><span class="tiny-badge">{{state.training_mode==='hr'?'PULS':'ERG'}}</span></div><div class="power-number">{{formatValue(metric('power'))}}<small>W</small></div><p class="muted" :title="state.power_measurement_note||''">{{state.power_measurement_note?'Ist nicht nachgewiesen · Gerät: '+formatValue(metric('reported_power'))+' W':state.mode==='demo'?'Simulierte Demo-Werte':'Gemessen · '+source('power')}}</p><div class="control-source" :class="{manual:state.control_mode==='manual_override'||powerDraft!==null}">{{state.control_mode==='manual_override'||powerDraft!==null?(state.running&&state.training_mode==='power'&&state.steps?.length?'Profil verschoben ('+(state.power_offset_watts>0?'+':'')+(state.power_offset_watts||0)+' W)':'Manuell angepasst'):state.control_mode==='hr'?'Pulsregelung':'Trainingsplan'}}</div><div class="target-control"><button :disabled="manualLocked||displayedTarget<=powerLimits.minimum" @click="setPower(displayedTarget-10)" aria-label="Leistung um 10 Watt reduzieren"><Minus :size="24"/><span>10 W</span></button><div><small>SOLLWERT ANGEFORDERT</small><b>{{displayedTarget}} <span>W</span></b></div><button :disabled="manualLocked||displayedTarget>=powerLimits.maximum" @click="setPower(displayedTarget+10)" aria-label="Leistung um 10 Watt erhöhen"><Plus :size="24"/><span>10 W</span></button></div><input class="live-watt-slider" aria-label="Zielleistung in Watt" type="range" :min="powerLimits.minimum" :max="powerLimits.maximum" :step="powerLimits.step" :value="displayedTarget" :disabled="manualLocked" @input="setPower(Number($event.target.value),'manual_slider')"><div class="range-label"><span>{{powerLimits.minimum}} W</span><span>{{powerLimits.maximum}} W</span></div><p class="target-ack" role="status">{{commandLabel}}</p><button class="text-button return-plan" :disabled="manualLocked||!state.running||!state.steps?.length" @click="returnToPlan">Zurück zum Trainingsplan</button><small v-if="state.running" class="next-power">Plan jetzt {{state.planned_target_watts??'—'}} W · nächste Stufe {{state.next_step?.watts??'—'}} W</small><button v-if="!state.running" class="button primary start-button" :disabled="busy||!online||state.zwift_detail?.armed||state.pending_save" @click="preflight"><Play :size="22" fill="currentColor"/>Training starten</button><div v-else class="ride-buttons"><button class="button primary" :disabled="busy||!online||state.zwift_detail?.armed" @click="action('pause')"><component :is="state.paused?'Play':'Pause'" :size="22"/>{{pendingAction==='pause'?'Bitte warten …':state.paused?'Fortsetzen':'Pause'}}</button><button class="button stop" :disabled="busy||!online" @click="action('stop')" aria-label="Training beenden"><Square :size="22"/><span>{{pendingAction==='stop'?'Speichert …':'Stopp'}}</span></button></div></section>
    </div>
    <section class="metrics cockpit-metrics" aria-label="Aktuelle Trainingswerte">
     <article class="card"><span><Timer :size="17"/>TRAININGSZEIT</span><b>{{clock(state.elapsed)}}</b><small>{{state.paused?'Pausiert':state.duration?'Noch '+clock(Math.max(0,state.duration-state.elapsed)):'Restzeit nicht festgelegt'}}</small></article>
     <article class="card"><span><Bike :size="17"/>GESCHWINDIGKEIT</span><b>{{formatValue(metric('speed'),1)}} <em :title="state.speed_measurement_note||''">{{state.speed_measurement_note?'km/h*':'km/h'}}</em></b><small>{{source('speed')}}</small></article>
     <article class="card"><span><Activity :size="17"/>TRITTFREQUENZ</span><b>{{formatValue(metric('cadence'))}} <em>U/min</em></b><small>{{source('cadence')}}</small></article>
     <article class="card"><span><Heart :size="17"/>HERZFREQUENZ</span><b>{{formatValue(metric('heart_rate'))}} <em>bpm</em></b><button class="text-button" @click="modal='hr'">{{state.hr_connected?'Pulsgurt verbunden':state.hr_reconnecting?'Pulsgurt wird erneut verbunden':'Pulsgurt verbinden'}} <ChevronRight :size="13"/></button></article>
     <article class="card"><span><Zap :size="17"/>ENERGIE</span><b>{{formatValue(metric('calories'))}} <em>kcal</em></b><small>{{metric('calories')==null?'Nicht verfügbar':source('calories')}} · {{formatValue(state.measurements?.energy?.available?state.measurements.energy.value:null)}} kJ mechanisch</small></article>
     <article class="card"><span><Bike :size="17"/>DISTANZ / ABSCHNITT</span><b>{{formatValue(state.elapsed>0?state.distance:null,2)}} <em :title="state.speed_measurement_note||''">{{state.speed_measurement_note?'km*':'km'}}</em></b><small>{{state.running&&state.steps?.length?'Abschnitt '+(state.step_index+1)+' / '+state.steps.length:'Kein Stufenplan aktiv'}}</small></article>
    </section>
    </div><details v-if="state.power_measurement_note" class="measurement-limits"><summary>Hinweise zu Daum-Gerätewerten</summary><p>{{state.power_measurement_note}} Ohne verlässliche Ist-Leistung werden daraus keine mechanische Arbeit, Watt/kg oder Fitnessvorschläge abgeleitet.</p><p v-if="state.speed_measurement_note">* {{state.speed_measurement_note}}</p></details><div class="bottom-grid"><section class="card chart-card"><div class="section-title"><h3>Dein Rhythmus</h3><span>LEISTUNG · LETZTE 90 SEK.</span></div><svg viewBox="0 0 600 120" class="power-chart" role="img" aria-label="Leistungsverlauf"><path d="M0 10H600M0 60H600M0 110H600" stroke="#e7ece6" stroke-dasharray="4 6"/><path :d="chart" fill="none" stroke="#b85b32" stroke-width="2.5" stroke-linejoin="round"/></svg><div class="range-label"><span>−90 s</span><span>Jetzt</span></div></section><section class="card next-card"><span class="eyebrow">MIT PLAN WEITERKOMMEN</span><h3>{{selectedPlan?.name || 'Dein nächster Schritt.'}}</h3><p>{{selectedPlan ? duration(selectedPlan)+' Minuten · bereit für deinen Ride':'Grundlage oder Intervalle? Finde dein Training.'}}</p><div class="progress" v-if="state.duration"><i :style="{width:progress+'%'}"></i></div><button class="text-button" @click="tab='Trainingspläne'">Trainingspläne entdecken <ArrowUpRight :size="16"/></button></section></div>
   </template>
   <template v-if="tab==='Trainingspläne'"><WorkoutCatalog :user-id="activeUser" :plans="plans" :disabled="busy||state.running||!online||state.zwift_detail?.armed" :request="request" @changed="load" @prepare="preparePlanId"/><CockpitFeatures section="plans" :user-id="activeUser" :plans="plans" :disabled="busy||state.running||!online||state.zwift_detail?.armed" :request="request" @changed="load" @select-plan="selectPlanId"/></template>
   <template v-if="tab==='KI-Coach'"><TrainingCoach :user-id="activeUser" :plans="plans" :disabled="busy||state.running||!online||state.zwift_detail?.armed" :request="request" @changed="load" @prepare="preparePlanId"/></template>
   <template v-if="tab==='Virtuelle Strecken'"><VirtualRoutes :user-id="activeUser" :state="state" :request="request"/></template>
   <template v-if="tab==='Planer'"><CockpitFeatures section="planner" :user-id="activeUser" :plans="plans" :disabled="busy||state.running||!online||state.zwift_detail?.armed" :request="request" @changed="load" @select-plan="selectPlanId"/></template><template v-if="tab==='Verbindungen'"><div class="connections"><article class="card connection"><span class="connection-icon"><Smartphone/></span><div><h2>iPhone als Trainingsbedienung</h2><p>Safari über WLAN · Livewerte und dieselbe zentrale Steuerung</p><small>Für Zwift auf dem iPhone zusätzlich „DAUM Studio“ per Bluetooth auswählen.</small></div><button class="button secondary" @click="modal='iphone'">iPhone verbinden</button></article><article class="card connection"><span class="connection-icon"><Bike/></span><div><h2>Daum Premium 8i</h2><p>LAN · 192.168.10.1:51955</p><small>{{state.mode==='demo'?'Demo aktiv · keine Bike-Steuerung':state.connected?'Verbunden · Steuerung bereit':'Nicht verbunden'}}</small></div><button class="button secondary" :disabled="busy||state.running" @click="action('mode',{mode:state.mode==='demo'?'daum':'demo'})">{{state.mode==='demo'?'Daum verbinden':'Zur Demo wechseln'}}</button></article><article class="card connection"><span class="connection-icon"><Heart/></span><div><h2>Garmin Pulsgurt</h2><p>Bluetooth Low Energy · Heart Rate Service</p><small>{{state.hr_connected?'Verbunden · '+(state.heart_rate??'Warte auf Signal'):'Gurt anlegen und Bluetooth-Suche starten'}}</small></div><button class="button secondary" @click="modal='hr'">Pulsgurt suchen</button></article><article class="card connection zwift-connection"><span class="connection-icon orange-icon"><Radio/></span><div><h2>Zwift Connect <span class="tiny-badge">FTMS · TESTVERSION</span></h2><p>{{state.zwift}}</p><small>In Zwift „DAUM Studio“ als Leistungsquelle und steuerbaren Trainer wählen.<br>ERG-Leistung, Streckensimulation, Kadenz und Puls. Noch nicht mit Zwift praktisch getestet.</small></div><button class="button secondary" :disabled="busy" @click="action(state.zwift_detail?.active?'zwift/stop':'zwift/start')">{{state.zwift_detail?.active?'Sender stoppen':'BLE-Sender starten'}}</button><section v-if="state.zwift_detail?.active" class="zwift-controls"><div class="zwift-guide"><b>{{state.control_owner==='zwift'?'Zwift hat die Steuerung':state.zwift_detail.armed?'Wartet auf Steuerungsanfrage von Zwift':'Nur Daten senden · Steuerung gesperrt'}}</b><p>{{state.mode==='demo'?'Demo: Bike-Werte und Widerstand sind simuliert.':'Daum-Modus: Zwift steuert den echten Widerstand.'}} Lokaler Stopp entzieht die Freigabe.</p></div><div v-if="!state.zwift_detail.armed" class="zwift-weights"><label>Fahrergewicht (kg)<input v-model.number="riderKg" type="number" min="35" max="200" :disabled="busy||state.running"></label><label>Radgewicht (kg)<input v-model.number="bikeKg" type="number" min="5" max="40" :disabled="busy||state.running"></label><button class="button primary" :disabled="busy||state.running" @click="action('zwift/control',{enabled:true,rider_kg:riderKg,bike_kg:bikeKg})">Zwift-Steuerung freigeben</button></div><div v-else class="zwift-weights"><button class="button stop" :disabled="busy" @click="action('zwift/control',{enabled:false})"><Square :size="16"/>Steuerung sperren &amp; stoppen</button></div><div class="zwift-details"><span>Modus <b>{{state.zwift_detail.mode}}</b></span><span>Steigung <b>{{state.zwift_detail.grade.toFixed(1)}} %</b></span><span>Wunsch <b>{{state.zwift_detail.requested_power}} W</b></span><span>Zurückgemeldet <b>{{state.applied_target_watts??'—'}} W</b></span><span>Letzter Befehl <b>{{state.zwift_detail.last_command || 'Noch keiner'}} · {{state.zwift_detail.last_result}}</b></span></div><small>25–400 W · Leistungsanstieg maximal 25 W/s · SIM berücksichtigt Gewicht, Steigung, Roll- und Luftwiderstand. Ohne bestätigte Ist-Leistungsmessung wird keine Wattmessung an Zwift gesendet; eine Leistungsanzeige dort ist dann nicht nachgewiesen.</small></section></article></div></template>

   <template v-if="tab==='Aktivitäten'"><CockpitFeatures section="activities" :user-id="activeUser" :plans="plans" :disabled="busy||state.running||!online||state.zwift_detail?.armed" :request="request" @changed="load" @select-plan="selectPlanId"/><section class="card activity-card"><div class="section-title"><h2>Deine letzten Rides</h2><button class="button secondary" @click="modal='export'"><Download :size="16"/>Apple Health &amp; Export</button></div><p v-if="!rides.length">Dein erster Ride wartet. Beendete Trainings werden hier gespeichert.</p><div class="activity-row" v-for="ride in rides" :key="ride.id"><span class="connection-icon"><Bike/></span><div><b>{{ride.mode==='demo'?'Demo · ':''}}{{ride.plan_name||'Training'}}</b><p>{{new Date((ride.started_at||ride.created.replace(' ','T')+'Z')).toLocaleString('de-DE')}} · {{ride.activity_type==='treadmill'?'Laufband · manuelle Eingabe':ride.training_mode==='hr'?'Pulsgeführt':'Watt / Zwift'}}</p></div><b>{{clock(ride.seconds)}}</b><b>{{formatValue(ride.distance,2)}} {{ride.mode==='daum'?'km*':'km'}}</b><span>{{formatValue(ride.energy)}} kJ</span><div v-if="ride.summary" class="ride-summary"><span>Ø Ist-Leistung {{formatValue(ride.summary.averages?.power_watts)}} W</span><span v-if="ride.summary.reported_unverified_power_watts!=null">Archivierte Gerätemeldung {{formatValue(ride.summary.reported_unverified_power_watts)}} W · unverifiziert</span><span>Ø Puls {{formatValue(ride.summary.averages?.heart_rate_bpm)}} bpm</span><span>Ø Kadenz {{formatValue(ride.summary.averages?.cadence_rpm)}} U/min</span><span v-if="ride.summary.manual_adjustments">{{ride.summary.manual_adjustments}} manuelle Eingriffe</span><small>{{ride.summary.source==='manual'?'Manuelle Eingabe':'Mittelwerte aus gültigen Messintervallen; Lücken bleiben unberücksichtigt.'}}</small></div><small v-if="ride.distance==null" class="export-note">TCX benötigt eine bekannte Distanz; CSV und JSON erhalten leere Werte.</small><div class="ride-exports"><button class="button secondary" :disabled="busy" @click="openRideTrace(ride)">Verlauf & Eingriffe</button><a v-for="format in (ride.distance==null?['csv','json']:['tcx','csv','json'])" class="button secondary" :href="'/api/rides/'+ride.id+'/export/'+format" :download="'Fitness-Cockpit-'+ride.id+'.'+format" :aria-label="format.toUpperCase()+' für Fahrt '+ride.id+' herunterladen'"><Download :size="13"/>{{format.toUpperCase()}}</a><button class="button secondary delete-ride" :disabled="busy" :aria-label="'Fahrt '+ride.id+' löschen'" @click="deleteRide(ride)">Löschen</button></div></div><p class="export-note">Neue Fahrten enthalten die aufgezeichnete Messspur; ältere Fahrten gegebenenfalls nur eine Zusammenfassung. Demo-Dateien sind gekennzeichnet. Mechanische kJ sind keine gemessenen Kalorien.</p></section></template>
   <footer>FITNESS-COCKPIT <span>Gemacht für deinen nächsten Kilometer.</span><span>{{state.mode==='demo'?'Demo · Bike-Werte simuliert':'Lokale Verbindung zum Daum'}}</span></footer>
  </main>
  <FullscreenTrainingView v-if="fullscreen.active" :mode="fullscreen.mode" :message="message" :ftp="profile.ftp_watts||150" :state="state" :steps="previewSteps" :samples="state.running||!selectedPlan?state.samples||[]:[]" :elapsed="previewElapsed" :requested-target="displayedTarget" :power-limits="powerLimits" :busy="busy" :manual-locked="manualLocked" :pending-action="pendingAction" :online="online" @exit="fullscreen.exit" @mode="fullscreen.enter" @power="setPower" @return-plan="returnToPlan" @action="fullscreenAction"/>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=''"><section class="modal card" role="dialog" aria-modal="true" :aria-label="modal==='trace'?'Trainingsverlauf':modal==='completion'?'Training abgeschlossen':modal==='preflight'?'Training vorbereiten':modal==='plan'?'Trainingsplan erstellen':modal==='hr'?'Pulsgurt verbinden':modal==='profile'?'Persönliche Trainingswerte':modal==='export'?'Export und Apple Health':modal==='iphone'?'iPhone verbinden':'Einstellungen'"><button class="close" @click="modal=''" aria-label="Schließen"><X/></button>
   <template v-if="modal==='trace'"><h2>Trainingsverlauf</h2><p v-if="!rideTrace">Verlauf wird geladen …</p><div v-else class="power-control-history"><h3>{{rideTrace.summary.plan_name}}</h3><p>Originalplan, angeforderte und gemessene Leistung bleiben getrennt. Spätere Profiländerungen verändern diese Einheit nicht.</p><WorkoutTimeline :steps="rideTrace.summary.statistics?.plan_steps||[]" :samples="rideTrace.samples||[]" :elapsed="rideTrace.summary.seconds" :power="null" :target="0" :live="false" :control-events="rideTrace.control_events||[]"/><p v-if="!rideTrace.control_events?.length">Für diese ältere oder manuelle Einheit ist kein Steuerprotokoll vorhanden.</p><ol><li v-for="(event,index) in rideTrace.control_events" :key="index" :class="{'manual-mark':event.source==='manual_button'||event.source==='manual_slider'}"><b>{{clock(event.elapsed_seconds)}} · {{eventLabel(event.source)}}</b><br>{{event.event}} · {{event.requested_target_watts??'—'}} W angefordert · {{event.applied_target_watts??'—'}} W bestätigt<span v-if="event.error"> · {{event.error}}</span></li></ol></div></template>
   <template v-if="modal==='completion'&&completed"><div class="completion-celebration" aria-hidden="true">✓</div><p class="eyebrow">{{completed.simulated?'DEMO ABGESCHLOSSEN':'TRAINING ABGESCHLOSSEN'}}</p><h2>Geschafft!</h2><p>{{completed.plan_name}}</p><div class="completion-grid"><span>Dauer<b>{{clock(completed.summary.duration_seconds)}}</b></span><span>Ø Leistung<b>{{formatValue(completed.summary.averages?.power_watts)}} W</b><small>Messzeit {{clock(completed.summary.coverage_seconds?.power_watts||0)}}</small></span><span>Ø Puls<b>{{formatValue(completed.summary.averages?.heart_rate_bpm)}} bpm</b><small>Messzeit {{clock(completed.summary.coverage_seconds?.heart_rate_bpm||0)}}</small></span><span>Ø Kadenz<b>{{formatValue(completed.summary.averages?.cadence_rpm)}} U/min</b><small>Messzeit {{clock(completed.summary.coverage_seconds?.cadence_rpm||0)}}</small></span><span>Mechanische Arbeit<b>{{formatValue(completed.summary.mechanical_energy_kj,1)}} kJ</b></span><span>Kalorien<b>{{completed.summary.calories_kcal==null?'Nicht verfügbar':formatValue(completed.summary.calories_kcal)+' kcal'}}</b></span></div><p>Mittelwerte beziehen sich auf gültige Messzeit. Fehlende Werte bleiben offen. Deine Einheit ist in der Historie gespeichert.</p><button class="button primary" @click="modal='';tab='Aktivitäten'">Auswertung & nächstes Training</button></template>
   <template v-if="modal==='preflight'"><span class="eyebrow">VORAB-CHECK</span><h2>Bereit für dein Training?</h2><div class="preflight-summary"><p><b>Benutzer:</b> {{users.find(u=>u.id===activeUser)?.name}}</p><p><b>Training:</b> {{selectedPlan?.name||'Freies Training / Puls-Cardio'}} · {{trainingMode==='hr'?'pulsgeführt':'wattgeführt'}}</p><p v-if="selectedPlan"><b>Leistungsanpassung:</b> {{selectedPlan.power_adjustment_watts>0?'+':''}}{{selectedPlan.power_adjustment_watts||0}} W · Intensität {{selectedPlan.meta?.calibration?100:intensity}} %</p><p v-if="selectedPlan?.power_basis==='example'"><b>Wattbasis ohne FTP:</b> Beispielbasis 150 W · Intensität und Profilanpassung gelten. Keine persönliche FTP hinterlegt.</p><p><b>Bike:</b> {{state.mode==='demo'?'Demo – Widerstand und Fahrwerte werden simuliert':state.connected?'Daum verbunden':'Daum nicht verbunden'}}</p><p><b>Puls:</b> {{state.hr_fresh?state.heart_rate+' bpm':state.hr_connected?'Verbunden – warte auf frisches Signal':'Kein Sensor verbunden'}}</p></div><button v-if="state.mode==='demo'||!state.connected" class="button secondary" :disabled="busy" @click="action('mode',{mode:'daum'})">Daum verbinden</button><button class="button primary" :disabled="busy||!online||state.running||state.zwift_detail?.armed" @click="connectAll"><Bluetooth :size="18"/>{{busy?'Verbindungen werden geprüft …':'Alles verbinden'}}</button><div v-if="connectionResults.length" class="connection-results" role="status"><p v-for="result in connectionResults" :class="{failed:!result.ok}">{{result.device==='daum'?'Daum':result.device==='zwift'?'Zwift-Sender':'Pulssensor'}}: {{result.message}}</p></div><fieldset class="device-selection"><legend>Zu verbindende Geräte</legend><label><input type="checkbox" value="daum" v-model="selectedDevices">Daum-Ergometer</label><label><input type="checkbox" value="hr" v-model="selectedDevices">Pulsgurt</label><label><input type="checkbox" value="zwift" v-model="selectedDevices">Zwift-Sender (optional)</label></fieldset><h3>Pulsgurt verbinden</h3><p>Gurt anlegen und anfeuchten. Die Bluetooth-Suche läuft auf dem Pi. Bei wattgeführtem Training ist der Pulsgurt optional.</p><button class="button secondary" :disabled="busy" @click="scan"><Bluetooth :size="18"/>{{busy?'Bitte warten …':'Pulssensor suchen'}}</button><button v-for="sensor in sensors" class="sensor" :disabled="busy" @click="action('hr/connect',{address:sensor.address})"><Heart :size="18"/><span>{{sensor.name}}<small>{{sensor.address}}</small></span><Plus :size="18"/></button><button v-if="state.hr_connected" class="text-button" :disabled="busy" @click="action('hr/disconnect')">Pulssensor trennen</button><details class="watch-help"><summary>Apple Watch als Pulssensor</summary><p>Über eine Bluetooth-Brücke wie HeartCast: App auf iPhone und Apple Watch öffnen, Pulsübertragung starten und das iPhone nahe am Pi lassen. Anschließend hier „Pulssensor suchen“ und den HeartCast-Sensor auswählen. Die native GymKit-Kopplung wird von {{productName}} nicht unterstützt. Diese Kombination ist am echten Gerät noch nicht geprüft.</p><a href="https://www.heartcast.app/faq-help-support-issues/" target="_blank" rel="noopener noreferrer">HeartCast-Anleitung</a></details><button v-if="selectedPlan" class="button secondary" :disabled="busy||!online||state.running" @click="validateSelectedPlan">Profil & Grenzen erneut prüfen</button><p v-if="validationToken" class="profile-validation" role="status">Profil geprüft und für diese Konfiguration vorbereitet.</p><p v-if="startBlocker" class="modal-error" role="alert">{{startBlocker}}</p><button v-if="selectedPlan?.power_basis==='example'||(trainingMode==='hr'&&(!profile.hr_max||!profile.hr_ceiling))" class="text-button" @click="openProfile">Persönliche Werte bearbeiten</button><p v-if="trainingMode==='power'" class="optional-pulse">Du kannst dieses Watttraining ohne Pulsgurt starten.</p><button v-if="trainingMode==='hr'" class="button secondary without-pulse" :disabled="busy||!online||state.running||state.zwift_detail?.armed||(state.mode==='daum'&&!state.connected)" @click="startWithoutHr">Ohne Pulsgurt starten · Watttraining</button><button class="button primary" :disabled="busy||!!startBlocker" @click="start"><Play :size="18"/>{{busy?'Bitte warten …':'Training jetzt starten'}}</button></template>
   <template v-if="modal==='hr'"><span class="eyebrow">DEIN PULS. LIVE IM RIDE.</span><h2>Pulsgurt verbinden</h2><p>Die Suche läuft auf dem Gerät, auf dem der Server läuft – später direkt auf dem Pi. Dein Garmin-Gurt muss Bluetooth unterstützen.</p><button class="button primary" :disabled="busy" @click="scan"><Bluetooth :size="18"/>{{busy?'Suche läuft …':'Bluetooth-Suche starten'}}</button><button v-for="sensor in sensors" class="sensor" :disabled="busy" @click="action('hr/connect',{address:sensor.address})"><Heart :size="18"/><span>{{sensor.name}}<small>{{sensor.address}}</small></span><Plus :size="18"/></button><button v-if="state.hr_connected" class="button secondary" @click="action('hr/disconnect')">Gurt trennen</button></template>


   <template v-if="modal==='iphone'"><span class="eyebrow">DEIN MOBILES COCKPIT</span><h2>iPhone verbinden</h2><p>1. iPhone und Pi im selben WLAN verbinden.<br>2. In Safari diese Adresse öffnen:</p><a class="phone-address" :href="appUrl">{{appUrl}}</a><p>3. In Safari auf „Teilen“ → „Zum Home-Bildschirm“ tippen. Damit öffnest du die Trainingsseite künftig direkt über ihr Symbol.</p><p>Du steuerst damit dieselbe Fahrt wie am Pi-Display. Für Zwift auf dem iPhone: Bluetooth aktivieren und DAUM Studio als Leistungsquelle und steuerbaren Trainer wählen.</p><button class="button secondary" @click="modal='export'">Export &amp; Apple Health ansehen</button></template>
   <template v-if="modal==='export'"><span class="eyebrow">DEIN TRAINING MITNEHMEN</span><h2>Export &amp; Apple Health</h2><p><b>TCX:</b> Trainingsdatei mit Zeit, Strecke und den verfügbaren Leistungs-, Kadenz- und Pulswerten. Geeignet für kompatible Trainingsplattformen, z. B. den Datei-Upload von Strava.</p><p><b>CSV / JSON:</b> Zusammenfassung und Messspur für eigene Auswertungen. Fehlende Werte bleiben leer. Demo-Fahrten bleiben als simuliert gekennzeichnet.</p><p><b>Apple Health:</b> Noch keine direkte HealthKit-Synchronisation. Die Pi-Webseite kann keine HealthKit-Berechtigung auf deinem iPhone anfordern. Du brauchst dafür eine iPhone-App, die Trainingsdateien importiert und die Schreibberechtigung für Health besitzt; die Unterstützung hängt von dieser App ab.</p><p>Auf dem iPhone: TCX bei der Fahrt herunterladen, in „Dateien“ speichern und über „Teilen“ an eine passende Import-App übergeben. Apple Health selbst wird hier nicht als TCX-Importziel angeboten.</p><p>Kalorien werden nicht aus mechanischen kJ erfunden. Das TCX-Pflichtfeld „Calories“ enthält 0 mit entsprechendem Hinweis. VO₂max wird weder berechnet noch exportiert.</p><p class="source-links"><a href="https://developer.apple.com/documentation/healthkit/authorizing-access-to-health-data" target="_blank" rel="noopener">Apple · HealthKit-Berechtigung ↗</a><a href="https://support.strava.com/en-us/articles/15402066-how-do-i-get-my-activities-to-strava" target="_blank" rel="noopener">Strava · Datei-Upload ↗</a></p></template>
   <template v-if="modal==='profile'"><span class="eyebrow">DEINE BASIS FÜR PASSENDES TRAINING</span><h2>Benutzerprofile &amp; Trainingswerte</h2><p>Aktiv: {{users.find(u=>u.id===activeUser)?.name}}. Die Auswahl gilt für das gemeinsame Bike auf allen Geräten und bleibt nach einem Neustart erhalten.</p><div class="profile-fields"><label>Benutzername<input v-model="userName" maxlength="60" placeholder="Name für neues Profil oder Umbenennung"></label></div><div class="profile-user-actions"><button class="button secondary" :disabled="busy||state.running||state.zwift_detail?.armed||!userName.trim()" @click="createUser">Neues Profil anlegen</button><button class="text-button" :disabled="busy||state.running||state.zwift_detail?.armed||!userName.trim()" @click="renameUser">Aktiven Benutzer umbenennen</button></div><p>Geburtsjahr, Größe und Geschlecht sind freiwillige Profilangaben. Sie werden nicht zur Schätzung von HFmax, Kalorien oder Belastbarkeit verwendet. Gewicht dient der Anzeige von Watt/kg.</p><p>Trage bekannte Werte ein. Die App berechnet keine HFmax aus dem Alter und führt keinen Maximaltest durch. FTP ist deine bekannte funktionelle Schwellenleistung, kein Wunschwert.</p><div class="profile-power-adjustment"><label for="profile-power-offset">Leistungsanpassung (W)</label><div class="watt-adjuster"><button class="button secondary" aria-label="Profil-Leistung um 5 Watt reduzieren" :disabled="busy||state.running||state.zwift_detail?.armed||profileForm.power_adjustment_watts<=-100" @click="adjustProfile(-5)"><Minus :size="20"/>5 W</button><input id="profile-power-offset" v-model.number="profileForm.power_adjustment_watts" type="number" min="-100" max="100" step="5" :disabled="busy||state.running||state.zwift_detail?.armed"><button class="button secondary" aria-label="Profil-Leistung um 5 Watt erhöhen" :disabled="busy||state.running||state.zwift_detail?.armed||profileForm.power_adjustment_watts>=100" @click="adjustProfile(5)"><Plus :size="20"/>5 W</button></div><p>Passt alle Planabschnitte für diesen Benutzer um bis zu ±100 W an, zusätzlich zur Intensität. Grenzen: 25–400 W. Die Orientierungsfahrt bleibt bei ihren festen Stufen. Im Pulsmodus gelten weiterhin deine Watt- und Pulsgrenzen. Mit „Persönliche Werte speichern“ übernehmen.</p></div><div class="profile-fields"><label>Minimale Trainingsleistung (W, optional)<input v-model.number="profileForm.power_min_watts" type="number" min="25" max="400" :disabled="busy||state.running||state.zwift_detail?.armed"></label><label>Maximale Trainingsleistung (W, optional)<input v-model.number="profileForm.power_max_watts" type="number" min="25" max="400" :disabled="busy||state.running||state.zwift_detail?.armed"></label><label>Geburtsjahr (optional)<input v-model.number="profileForm.birth_year" type="number" min="1900" :max="new Date().getFullYear()" :disabled="busy||state.running||state.zwift_detail?.armed"></label><label>Gewicht (kg, für Watt/kg)<input v-model.number="profileForm.weight_kg" type="number" min="20" max="300" step="0.1" :disabled="busy||state.running||state.zwift_detail?.armed"></label><label>Körpergröße (cm, optional)<input v-model.number="profileForm.height_cm" type="number" min="80" max="250" :disabled="busy||state.running||state.zwift_detail?.armed"></label><label>Geschlecht (optional)<select v-model="profileForm.sex" :disabled="busy||state.running||state.zwift_detail?.armed"><option :value="null">Keine Angabe</option><option value="female">Weiblich</option><option value="male">Männlich</option><option value="diverse">Divers</option></select></label><label>Lockere Ausgangsleistung (W, keine FTP)<input :disabled="busy||state.running||state.zwift_detail?.armed" v-model.number="profileForm.comfortable_watts" type="number" min="25" max="250" placeholder="Aus Orientierungsfahrt / eigener Erfahrung"></label><label>FTP / Schwellenleistung (W)<input :disabled="busy||state.running||state.zwift_detail?.armed" v-model.number="profileForm.ftp_watts" type="number" min="50" max="400" placeholder="Noch nicht hinterlegt"></label><label>Persönliche HFmax (bpm)<input :disabled="busy||state.running||state.zwift_detail?.armed" v-model.number="profileForm.hr_max" type="number" min="100" max="230" placeholder="Bekannter individueller Wert"></label><label>Persönliche Pulsgrenze (bpm)<input :disabled="busy||state.running||state.zwift_detail?.armed" v-model.number="profileForm.hr_ceiling" type="number" min="70" max="220" placeholder="Automatischer Stopp ab diesem Wert"></label><label>Minimale Leistung im Pulsmodus (W)<input :disabled="busy||state.running||state.zwift_detail?.armed" v-model.number="profileForm.hr_min_watts" type="number" min="25" max="200"></label><label>Maximale Leistung im Pulsmodus (W)<input :disabled="busy||state.running||state.zwift_detail?.armed" v-model.number="profileForm.hr_max_watts" type="number" min="30" max="400"></label></div><p>Bei fehlendem Signal wird auf 25 W reduziert und pausiert. Die Pulsgrenze ist eine technische Stoppbedingung und ersetzt keine medizinische Überwachung. Hohe Zielzonen werden unter dieser Grenze gedeckelt.</p><button class="button primary" :disabled="busy||state.running||state.zwift_detail?.armed" @click="saveProfile">Persönliche Werte speichern <Check :size="17"/></button></template>
   <template v-if="modal==='settings'"><span class="eyebrow">DEIN SETUP</span><h2>Cockpit-Einstellungen</h2><div class="auto-off-settings"><h3>Automatisch abschalten</h3><p>Pi nach 5 Minuten ohne direkte LAN-Verbindung zum Daum herunterfahren. Ein laufendes Training wird vorher gespeichert.</p><p role="status">Status: <b>{{powerSettings.available?(powerSettings.enabled?'Eingeschaltet':'Ausgeschaltet'):'Auf diesem Gerät noch nicht installiert'}}</b></p><button class="button secondary" :disabled="busy||!powerSettings.available" :aria-pressed="powerSettings.enabled" @click="toggleAutoOff">{{powerSettings.enabled?'Automatisches Abschalten ausschalten':'Automatisches Abschalten einschalten'}}</button><p>Nach dem Herunterfahren startet der Pi beim erneuten Anschließen des Netzteils. Das Einschalten des Daum allein startet den Pi ohne Zusatzhardware nicht.</p></div><button class="button secondary" @click="openProfile">Persönliche Trainingswerte</button><p>Pi: GHAPI3 · Benutzer: gha<br>Daum: 192.168.10.1 · Pi-LAN: 192.168.10.2</p><div class="setting-row"><span>Bike-Modus</span><b>{{state.mode==='demo'?'Simulation':'Daum LAN'}}</b></div><p>Demo-Werte sind simuliert. Ein echter Pulsgurt liefert auch in der Demo echte Pulswerte.</p><button class="button primary" @click="modal='';tab='Verbindungen'">Verbindungen verwalten <ArrowUpRight :size="17"/></button></template>
   <template v-if="modal==='plan'"><span class="eyebrow">DEIN EIGENER RHYTHMUS</span><h2>Trainingsplan erstellen</h2><label>Planname<input v-model="planName" maxlength="80"></label><div class="step-labels"><span>Abschnitt</span><span>Sekunden</span><span>Watt</span></div><div class="step-editor" v-for="(step,i) in steps"><input v-model="step.name" aria-label="Abschnittname"><input v-model.number="step.seconds" type="number" min="10" max="7200" aria-label="Dauer in Sekunden"><input v-model.number="step.watts" type="number" min="25" max="400" aria-label="Leistung in Watt"><button @click="steps.splice(i,1)" :disabled="steps.length===1" aria-label="Abschnitt entfernen"><X :size="16"/></button></div><button class="text-button" @click="steps.push({name:'Intervall',seconds:60,watts:150})"><Plus :size="17"/>Abschnitt hinzufügen</button><button class="button primary" :disabled="busy" @click="save">Trainingsplan speichern <Check :size="17"/></button></template>
   <p v-if="message" class="modal-error" role="alert">{{message}}</p>
  </section></div>
 </div>`
}).mount('#app');
